package com.example.notitia.bridge

// The Rust core as the shared code sees it. On Android, Kotlin generated by UniFFI holds it; on the iPhone, a Swift
// class does. Swift cannot suspend, emit a Flow or throw one of our exceptions: every function here blocks, takes
// and returns plain values, and reports a failure as a value. The callers move the calls off the main thread.
interface NotitiaCore {
    fun meetingSummary(path: String): CoreResult<MeetingSummary>

    // The other way: the core calls back the host it is given, from a thread of its own.
    fun ask(host: HostProbe, question: String): String
}

// A number rather than an Instant: Swift builds this object, and it cannot build a Kotlin Instant.
data class MeetingSummary(val id: String, val title: String?, val startedAtMs: Long)

// Top-level and generic rather than nested: this is the shape Swift names and builds without surprise.
sealed class CoreResult<out T : Any>

data class CoreOk<out T : Any>(val value: T) : CoreResult<T>()

data class CoreFailed<out T : Any>(val failure: CoreFailure) : CoreResult<T>()

// Broken is a fault of the core itself or of its bridge, never of the file.
enum class CoreFailure { Unreadable, NotAMeeting, NewerFormat, Broken }

// Held by the app, called by the core: the system's AI will reach the core through an interface like this one.
fun interface HostProbe {
    fun answer(question: String): String
}
